#[async_trait]
pub trait Agent<Input>: Send + Sync {
    type Response: Send + Sync;
    type Error: Send + Sync;

    /// Process input and produce response
    async fn process(
        &self,
        input: Input,
    ) -> Result<Self::Response, Self::Error>;

    /// Get agent identifier
    fn id(&self) -> &str;
}
